// 1.
deviceState = new CO( "3/0/12", "switch", widget( "DeviceDisplay" ));
// 2.
deviceControl = new CO( "3/1/12", "switch" );

// 3.
System.ConnectionCheck = function( Connected ) {
  status = widget( "CommunicationStatus" );
  if( Connected ) {
    status.setImage( System.Image( "ConnectionStateOK" ));
  } else {
    status.setImage( System.Image( "ConnectionStateError" ));
  }
}

// 4.
System.SetReadObjects( new Array(
  deviceState
));

// 5.
System.PageUpdate = function( CO ) {
  if( CO.widget == null ) {
    // do nothing
  } else if( CO.value == "true" ) {
    CO.widget.setImage( CF.widget( "On1", "Res", "Sys" ).getImage(), 0 );
    CO.widget.setImage( CF.widget( "On2", "Res", "Sys" ).getImage(), 1 );
  } else {
    CO.widget.setImage( CF.widget( "IOff1", "Res", "Sys" ).getImage(), 0 );
    CO.widget.setImage( CF.widget( "IOff2", "Res", "Sys" ).getImage(), 1 );
  }
}

// 2.
deviceControl = new CO( "3/1/12", "switch" );

// 3.
System.ConnectionCheck = function( Connected ) {
  status = widget( "CommunicationStatus" );
  if( Connected ) {
    status.setImage( System.Image( "ConnectionStateOK" ));
  } else {
    status.setImage( System.Image( "ConnectionStateError" ));
  }
}

// 4.
System.SetReadObjects( null );

// 5.
System.PageUpdate = null;

var DEBUG = true;
var CORE_PERIOD = 200;
var COMMUNICATE_EACH = 4; // count of periods

